"""Honest macro metrics, class supports, and root-stage diagnostics."""
import argparse,json
from pathlib import Path
import numpy as np
from PIL import Image
import common as c
p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);a=p.parse_args();r=a.run;overview=[];diagnostics=[];supports=[];rows=c.rows(r/'data/paired_manifest.csv')
for model in c.MODELS:
 meta=json.loads((r/model/'training_run.json').read_text());d=json.loads((r/model/'metrics.json').read_text())
 for ref in ['revised','original']:
  z=d['test'][ref]['end_to_end'];cl=z['classes'];overview.append(dict(model=model,display_name=c.MODEL_NAMES[model],reference='U-Net-derived reference' if ref=='revised' else 'Original human audit',Precision=float(np.mean([v['Precision'] if v['Precision'] is not None else 0 for v in cl])),Recall=float(np.mean([v['Recall'] if v['Recall'] is not None else 0 for v in cl])),Dice=z['macro_Dice'],IoU=float(np.mean([v['IoU'] if v['IoU'] is not None else 0 for v in cl])),selected_epoch=meta['selected_epoch'],epochs_trained=24,internal_test_date_pairs=18,independent_external_images=0))
 for t in c.PERIODS:
  gt=np.array(Image.open(r/'data/revised'/f'{t}_classes.png'));pred=np.array(Image.open(r/model/'four_period_prediction'/f'{t}_temporal_classes.png'));g=gt>0;q=pred>0;tp=int((g&q).sum());fp=int((~g&q).sum());fn=int((g&~q).sum());diagnostics.append(dict(model=model,period=t,scope='Full upper field, descriptive and includes training pixels',root_Dice=2*tp/(2*tp+fp+fn),root_Recall=tp/(tp+fn),reference_root_pixels=int(g.sum()),predicted_root_pixels=int(q.sum())))
for ref in ['original','revised']:
 for split in ['train','val','test']:
  for t in c.PERIODS[1:]:
   gt=np.array(Image.open(r/'data'/ref/f'{t}_classes.png'));cc=np.zeros(5,np.int64)
   for row in rows:
    if row['split']==split and row['current']==t:
     x,y=int(row['x']),int(row['y']);patch=gt[y:y+256,x:x+256];cc[:4]+=[int((patch==k).sum()) for k in range(4)];cc[4]+=int((patch==255).sum())
   for k,n in zip([0,1,2,3,255],cc):supports.append(dict(reference=ref,split=split,period=t,class_id=k,pixels=int(n)))
c.csvout(r/'tables/accuracy_summary.csv',overview);c.csvout(r/'tables/full_field_binary_root_diagnostics.csv',diagnostics);c.csvout(r/'tables/class_supports.csv',supports)
s=['# Three temporal models — internal same-position evaluation','','Training / validation / internal test: 200 / 20 / 24 RGB views, representing 150 / 15 / 18 adjacent-date pairs. All dates at a spatial window share a split. External independent images: 0.','','| Reference | Model | Precision | Recall | Macro Dice | IoU | Selected epoch |','|---|---|---:|---:|---:|---:|---:|']
for v in overview:s.append(f"| {v['reference']} | {v['display_name']} | {v['Precision']:.4f} | {v['Recall']:.4f} | {v['Dice']:.4f} | {v['IoU']:.4f} | {v['selected_epoch']} / 24 |")
s+=['','Macro metrics average persistent, newly observed and tip-growth classes after pooling confusion counts over 18 internal test date-pairs. Background and T1 baseline are excluded. A defined class with no predicted positives has Precision 0 in this summary. Original-human figures are a separate audit, not an independent external test.','', 'The reference is generated by the starting v15 U-Net itself. Perfect U-Net reference agreement is circular and is not independent accuracy. All three heads were trained for 24 epochs; epoch 0 can be retained if no checkpoint improves validation performance. Binary root detectors remain frozen. Full-field RGB panels include fitting pixels and are qualitative.']
(r/'tables/ACCURACY.md').write_text('\n'.join(s)+'\n');print('\n'.join(s),flush=True)
